    def h_shape(dr,dc):
        for x in range(dc-4,dc+1):
            out[dr][x]=2; out[dr+5][x]=2
        out[dr][dc-2:dc+3]=[5]*5
        return out
    res=[]
    for (r,c) in pts:
        res.append(v_shape(r,c)); res.append(h_shape(r,c))
    for o in res: out=o
    return out
